<template>
  <div class="view-gallery-responsive-live">
    <div class="responsive-scene-switch" role="tablist" aria-label="Choose the scene shown on both screens">
      <button v-for="scene in scenes" :key="scene.id" type="button" role="tab" :aria-selected="selectedScene === scene.id" @click="selectedScene = scene.id">{{ scene.label }}</button>
    </div>
    <div class="responsive-device-switch" role="tablist" aria-label="Choose a phone orientation">
      <button v-for="item in devices" :key="item.id" type="button" role="tab" :aria-selected="selected === item.id" @click="selected = item.id">{{ item.label }}</button>
    </div>
    <article v-for="item in devices" :key="item.id" :class="[`is-${item.id}`, { 'is-active': selected === item.id }]">
      <header><span>{{ item.label }}</span></header>
      <div class="responsive-device-stage">
        <ViewGalleryLiveStage
          :mode="selectedScene"
          :active="active && (wideLayout || selected === item.id)"
          :design-width="item.width"
          :design-height="item.height"
          show-controls
          compact
        />
      </div>
    </article>
  </div>
</template>

<script>
import ViewGalleryLiveStage from './ViewGalleryLiveStage.vue';

export default {
  name: 'ViewGalleryResponsiveLive',
  components: { ViewGalleryLiveStage },
  props: { active: Boolean },
  data: () => ({
    selected: 'landscape',
    selectedScene: 'exhibition',
    wideLayout: true,
    scenes: [
      { id: 'gallery', label: 'Gallery' },
      { id: 'exhibition', label: 'Exhibition' },
    ],
    devices: [
      { id: 'landscape', label: 'Landscape', width: 932, height: 430 },
      { id: 'portrait', label: 'Portrait', width: 390, height: 844 },
    ],
  }),
  mounted() {
    this._wideQuery = window.matchMedia('(min-width: 761px)');
    this.syncLayout();
    this._wideQuery.addEventListener('change', this.syncLayout);
  },
  beforeUnmount() { this._wideQuery?.removeEventListener('change', this.syncLayout); },
  methods: { syncLayout() { this.wideLayout = this._wideQuery?.matches ?? true; } },
};
</script>

